1	/**
2	 * 体态检测服务
3	 * 负责传感器数据采集、体态分析、异常检测
4	 */
5	
6	import sensor from '@system.sensor'
7	import storage from '@system.storage'
8	
9	class PostureService {
10	  constructor() {
11	    this.isMonitoring = false
12	    this.sensorData = {
13	      accelerometer: { x: 0, y: 0, z: 0 },
14	      gyroscope: { x: 0, y: 0, z: 0 }
15	    }
16	    this.postureHistory = []
17	    this.lastCheckTime = null
18	    this.checkInterval = 30 * 60 * 1000 // 30分钟
19	    this.timer = null
20	  }
21	
22	  /**
23	   * 开始监测
24	   */
25	  startMonitoring(callback) {
26	    if (this.isMonitoring) return
27	
28	    this.isMonitoring = true
29	    this.onStatusChange = callback
30	
31	    // 订阅加速度传感器
32	    sensor.subscribeAccelerometer({
33	      interval: 'normal',
34	      success: (data) => {
35	        this.sensorData.accelerometer = data
36	        this.analyzePosture()
37	      },
38	      fail: (err) => {
39	        console.error('加速度传感器错误:', err)
40	      }
41	    })
42	
43	    // 订阅陀螺仪传感器
44	    sensor.subscribeGyroscope({
45	      interval: 'normal',
46	      success: (data) => {
47	        this.sensorData.gyroscope = data
48	      },
49	      fail: (err) => {
50	        console.error('陀螺仪传感器错误:', err)
51	      }
52	    })
53	
54	    // 定时检测
55	    this.timer = setInterval(() => {
56	      this.checkPosture()
57	    }, this.checkInterval)
58	
59	    console.log('体态监测已启动')
60	  }
61	
62	  /**
63	   * 停止监测
64	   */
65	  stopMonitoring() {
66	    if (!this.isMonitoring) return
67	
68	    this.isMonitoring = false
69	
70	    // 取消传感器订阅
71	    sensor.unsubscribeAccelerometer()
72	    sensor.unsubscribeGyroscope()
73	
74	    // 清除定时器
75	    if (this.timer) {
76	      clearInterval(this.timer)
77	      this.timer = null
78	    }
79	
80	    console.log('体态监测已停止')
81	  }
82	
83	  /**
84	   * 分析体态
85	   * 基于加速度和陀螺仪数据判断体态
86	   */
87	  analyzePosture() {
88	    const accel = this.sensorData.accelerometer
89	    const gyro = this.sensorData.gyroscope
90	
91	    // 计算倾斜角度
92	    const pitch = Math.atan2(accel.y, Math.sqrt(accel.x * accel.x + accel.z * accel.z)) * 180 / Math.PI
93	    const roll = Math.atan2(accel.x, Math.sqrt(accel.y * accel.y + accel.z * accel.z)) * 180 / Math.PI
94	
95	    // 判断体态
96	    const posture = this.classifyPosture(pitch, roll)
97	
98	    // 更新历史记录
99	    this.postureHistory.push({
100	      timestamp: Date.now(),
101	      posture: posture,
102	      pitch: pitch,
103	      roll: roll,
104	      accel: { ...accel },
105	      gyro: { ...gyro }
106	    })
107	
108	    // 保持最近100条记录
109	    if (this.postureHistory.length > 100) {
110	      this.postureHistory.shift()
111	    }
112	
113	    return posture
114	  }
115	
116	  /**
117	   * 分类体态
118	   * @param {number} pitch - 俯仰角
119	   * @param {number} roll - 横滚角
120	   * @returns {string} 体态类型
121	   */
122	  classifyPosture(pitch, roll) {
123	    // 良好坐姿：身体基本直立，轻微前倾
124	    if (pitch > -20 && pitch < 20 && Math.abs(roll) < 15) {
125	      return 'good'
126	    }
127	
128	    // 前倾过度
129	    if (pitch <= -20) {
130	      return 'leaning_forward'
131	    }
132	
133	    // 后仰
134	    if (pitch >= 20) {
135	      return 'leaning_back'
136	    }
137	
138	    // 侧倾
139	    if (Math.abs(roll) >= 15) {
140	      return 'tilted'
141	    }
142	
143	    return 'unknown'
144	  }
145	
146	  /**
147	   * 定时检查体态
148	   */
149	  checkPosture() {
150	    const posture = this.analyzePosture()
151	    const isGood = posture === 'good'
152	
153	    // 通知回调
154	    if (this.onStatusChange) {
155	      this.onStatusChange({
156	        isGood: isGood,
157	        posture: posture,
158	        timestamp: Date.now()
159	      })
160	    }
161	
162	    this.lastCheckTime = Date.now()
163	    return { isGood, posture }
164	  }
165	
166	  /**
167	   * 获取当前体态状态
168	   */
169	  getCurrentPosture() {
170	    if (this.postureHistory.length === 0) {
171	      return { posture: 'unknown', isGood: false }
172	    }
173	
174	    const latest = this.postureHistory[this.postureHistory.length - 1]
175	    return {
176	      posture: latest.posture,
177	      isGood: latest.posture === 'good',
178	      pitch: latest.pitch,
179	      roll: latest.roll
180	    }
181	  }
182	
183	  /**
184	   * 获取体态统计
185	   */
186	  getPostureStats() {
187	    if (this.postureHistory.length === 0) {
188	      return {
189	        goodCount: 0,
190	        badCount: 0,
191	        goodPercent: 0,
192	        mostCommon: 'unknown'
193	      }
194	    }
195	
196	    let goodCount = 0
197	    let badCount = 0
198	    const postureCounts = {}
199	
200	    this.postureHistory.forEach(record => {
201	      if (record.posture === 'good') {
202	        goodCount++
203	      } else {
204	        badCount++
205	      }
206	
207	      postureCounts[record.posture] = (postureCounts[record.posture] || 0) + 1
208	    })
209	
210	    // 找出最常见的体态
211	    let mostCommon = 'unknown'
212	    let maxCount = 0
213	    Object.entries(postureCounts).forEach(([posture, count]) => {
214	      if (count > maxCount) {
215	        maxCount = count
216	        mostCommon = posture
217	      }
218	    })
219	
220	    return {
221	      goodCount,
222	      badCount,
223	      goodPercent: Math.round((goodCount / this.postureHistory.length) * 100),
224	      mostCommon
225	    }
226	  }
227	
228	  /**
229	   * 设置检测间隔
230	   */
231	  setCheckInterval(minutes) {
232	    this.checkInterval = minutes * 60 * 1000
233	
234	    // 如果正在监测，重启定时器
235	    if (this.isMonitoring && this.timer) {
236	      clearInterval(this.timer)
237	      this.timer = setInterval(() => {
238	        this.checkPosture()
239	      }, this.checkInterval)
240	    }
241	  }
242	
243	  /**
244	   * 保存数据到本地存储
245	   */
246	  saveData() {
247	    const today = this.getDateKey()
248	    const stats = this.getPostureStats()
249	
250	    storage.set({
251	      key: `posture_${today}`,
252	      value: JSON.stringify({
253	        stats: stats,
254	        history: this.postureHistory.slice(-50) // 只保存最近50条
255	      }),
256	      success: () => {
257	        console.log('体态数据已保存')
258	      }
259	    })
260	  }
261	
262	  /**
263	   * 加载历史数据
264	   */
265	  loadData(date) {
266	    return new Promise((resolve, reject) => {
267	      const key = `posture_${date || this.getDateKey()}`
268	      storage.get({
269	        key: key,
270	        success: (data) => {
271	          if (data) {
272	            resolve(JSON.parse(data))
273	          } else {
274	            resolve(null)
275	          }
276	        },
277	        fail: (err) => {
278	          reject(err)
279	        }
280	      })
281	    })
282	  }
283	
284	  /**
285	   * 获取日期键
286	   */
287	  getDateKey() {
288	    const now = new Date()
289	    return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`
290	  }
291	
292	  /**
293	   * 获取体态描述
294	   */
295	  getPostureDescription(posture) {
296	    const descriptions = {
297	      'good': '✅ 良好坐姿',
298	      'leaning_forward': '⚠️ 过度前倾',
299	      'leaning_back': '⚠️ 过度后仰',
300	      'tilted': '⚠️ 身体侧倾',
301	      'unknown': '❓ 未知状态'
302	    }
303	    return descriptions[posture] || descriptions['unknown']
304	  }
305	
306	  /**
307	   * 获取改善建议
308	   */
309	  getImprovementTips(posture) {
310	    const tips = {
311	      'good': ['继续保持当前坐姿！', '记得定时起身活动。'],
312	      'leaning_forward': ['调整椅子高度，使双脚平放地面。', '将屏幕抬高至与视线平齐。', '收紧核心肌群，保持背部挺直。'],
313	      'leaning_back': ['调整靠背角度，保持90-100度。', '使用腰靠支撑腰部曲线。', '避免长时间后仰看手机。'],
314	      'tilted': ['检查桌子是否平整。', '避免单侧负重。', '均衡使用双手。'],
315	      'unknown': ['请保持正确坐姿。']
316	    }
317	    return tips[posture] || tips['unknown']
318	  }
319	}
320	
321	// 导出单例
322	export default new PostureService()
