1	/**
2	 * 存储工具类
3	 * 封装 @system.storage，提供便捷的数据持久化方法
4	 */
5	
6	import storage from '@system.storage'
7	
8	class StorageUtil {
9	  /**
10	   * 获取数据
11	   */
12	  static get(key) {
13	    return new Promise((resolve, reject) => {
14	      storage.get({
15	        key: key,
16	        success: (data) => {
17	          if (data) {
18	            try {
19	              resolve(JSON.parse(data))
20	            } catch (e) {
21	              resolve(data)
22	            }
23	          } else {
24	            resolve(null)
25	          }
26	        },
27	        fail: (err) => {
28	          reject(err)
29	        }
30	      })
31	    })
32	  }
33	
34	  /**
35	   * 设置数据
36	   */
37	  static set(key, value) {
38	    return new Promise((resolve, reject) => {
39	      const data = typeof value === 'object' ? JSON.stringify(value) : value
40	      storage.set({
41	        key: key,
42	        value: data,
43	        success: () => {
44	          resolve()
45	        },
46	        fail: (err) => {
47	          reject(err)
48	        }
49	      })
50	    })
51	  }
52	
53	  /**
54	   * 删除数据
55	   */
56	  static delete(key) {
57	    return new Promise((resolve, reject) => {
58	      storage.delete({
59	        key: key,
60	        success: () => {
61	          resolve()
62	        },
63	        fail: (err) => {
64	          reject(err)
65	        }
66	      })
67	    })
68	  }
69	
70	  /**
71	   * 清空所有数据
72	   */
73	  static clear() {
74	    return new Promise((resolve, reject) => {
75	      storage.clear({
76	        success: () => {
77	          resolve()
78	        },
79	        fail: (err) => {
80	          reject(err)
81	        }
82	      })
83	    })
84	  }
85	
86	  /**
87	   * 获取所有键
88	   */
89	  static getAllKeys() {
90	    return new Promise((resolve, reject) => {
91	      storage.getAllKeys({
92	        success: (data) => {
93	          resolve(data)
94	        },
95	        fail: (err) => {
96	          reject(err)
97	        }
98	      })
99	    })
100	  }
101	
102	  /**
103	   * 检查键是否存在
104	   */
105	  static async has(key) {
106	    try {
107	      const value = await this.get(key)
108	      return value !== null
109	    } catch (e) {
110	      return false
111	    }
112	  }
113	
114	  /**
115	   * 获取带过期时间的数据
116	   */
117	  static async getWithExpiry(key) {
118	    try {
119	      const data = await this.get(key)
120	      if (!data) return null
121	
122	      if (data.expiry && Date.now() > data.expiry) {
123	        await this.delete(key)
124	        return null
125	      }
126	
127	      return data.value
128	    } catch (e) {
129	      return null
130	    }
131	  }
132	
133	  /**
134	   * 设置带过期时间的数据
135	   */
136	  static setWithExpiry(key, value, ttlMs) {
137	    const data = {
138	      value: value,
139	      expiry: Date.now() + ttlMs
140	    }
141	    return this.set(key, data)
142	  }
143	
144	  /**
145	   * 批量获取
146	   */
147	  static async getMultiple(keys) {
148	    const results = {}
149	    for (const key of keys) {
150	      try {
151	        results[key] = await this.get(key)
152	      } catch (e) {
153	        results[key] = null
154	      }
155	    }
156	    return results
157	  }
158	
159	  /**
160	   * 批量设置
161	   */
162	  static async setMultiple(data) {
163	    const promises = Object.entries(data).map(([key, value]) => {
164	      return this.set(key, value)
165	    })
166	    return Promise.all(promises)
167	  }
168	
169	  /**
170	   * 原子操作：读取-修改-写入
171	   */
172	  static async update(key, modifier) {
173	    const current = await this.get(key)
174	    const updated = modifier(current)
175	    await this.set(key, updated)
176	    return updated
177	  }
178	
179	  /**
180	   * 计数器自增
181	   */
182	  static async increment(key, amount = 1) {
183	    return this.update(key, (current) => {
184	      const num = typeof current === 'number' ? current : 0
185	      return num + amount
186	    })
187	  }
188	
189	  /**
190	   * 列表追加
191	   */
192	  static async append(key, item, maxItems = 100) {
193	    return this.update(key, (current) => {
194	      const list = Array.isArray(current) ? current : []
195	      list.push(item)
196	      if (list.length > maxItems) {
197	        list.shift()
198	      }
199	      return list
200	    })
201	  }
202	}
203	
204	export default StorageUtil
